using System;
using System.Collections.Generic;
using System.Drawing;
using System.Globalization;
using System.Linq;
using System.Windows.Forms;
namespace NightLens {
class BortleForm:Form {
    public List<SkySite> Sites;Settings settings;NumericUpDown bortle,sqm;Label status;
    public BortleForm(Settings s){settings=s;Sites=Json.Read<List<SkySite>>(Json.Write(s.SkySites??new List<SkySite>()));Style.Form(this);Text="Sky brightness settings";Style.FitScreen(this,780,410);var root=Style.Grid(1,36,42,59,76,-100,39);root.Padding=new Padding(12);Controls.Add(root);root.Controls.Add(Style.Label("Sky brightness at this location",18,true),0,0);root.Controls.Add(Style.Label(s.Place+" · "+s.Lat.ToString("0.0000")+", "+s.Lon.ToString("0.0000")+"\nValues are estimates unless measured at your observing site.",9),0,1);var row=Style.Grid(2,-100);var site=SkySite.At(s);bortle=new NumericUpDown{Minimum=0,Maximum=9,DecimalPlaces=1,Increment=.1m,Value=site==null?0:(decimal)site.Bortle};sqm=new NumericUpDown{Minimum=0,Maximum=23,DecimalPlaces=2,Increment=.01m,Value=site?.Sqm==null?0:(decimal)site.Sqm.Value};row.Controls.Add(Style.Field("Bortle 1–9 (0 = not set)",bortle),0,0);row.Controls.Add(Style.Field("SQM mag/arcsec² (0 = unknown)",sqm),1,0);root.Controls.Add(row,0,2);root.Controls.Add(Style.Label("Open the map at this location and read its baseline Bortle / SQM. Map values are estimates, separate from the moonlight simulation. Confirm them here; this version does not sync map changes automatically. Saving applies this value within 0.5 km of the current coordinates.",9.5f),0,3);var buttons=Style.Grid(2,-100);buttons.Controls.Add(Style.Button("Open LightPollutionMap.app",(a,b)=>System.Diagnostics.Process.Start(MapUrl(s.Lat,s.Lon))),0,0);status=Style.Label(site==null?"No matching sky-brightness sample.":site.Source+"\n"+(site.AreaEstimate?"Area estimate — verify your exact site.":"Saved site value."),9);buttons.Controls.Add(status,1,0);root.Controls.Add(buttons,0,4);root.Controls.Add(Style.Button("Save sky brightness",(a,b)=>{if(bortle.Value>0&&bortle.Value<1){status.Text="Choose Bortle 1–9, or 0 for unknown.";return;}Sites.RemoveAll(x=>SkySite.Distance(s.Lat,s.Lon,x.Lat,x.Lon)<=Math.Max(.5,x.RadiusKm));if(bortle.Value>0)Sites.Add(new SkySite{Lat=s.Lat,Lon=s.Lon,Bortle=(double)bortle.Value,Sqm=sqm.Value==0?(double?)null:(double)sqm.Value,RadiusKm=.5,Source="User-confirmed / map entry · "+DateTime.Now.ToString("yyyy-MM-dd"),AreaEstimate=false});DialogResult=DialogResult.OK;Close();}),0,5);}
    public static string MapUrl(double lat,double lon){return "https://lightpollutionmap.app/?lat="+Net.Coord(lat)+"&lng="+Net.Coord(lon)+"&zoom=13";}
}
static class CaptureUI {
    public static void Attach(Control card,CaptureGuide guide,Form owner){Action<Control> attach=null;attach=c=>{c.Cursor=Cursors.Hand;c.AccessibleDescription="Open capture guidance";c.Click+=(a,b)=>Show(guide,owner);foreach(Control child in c.Controls)attach(child);};attach(card);}
    public static Form Create(CaptureGuide guide){var form=new Form();Style.Form(form);form.Text="Object capture guidance";Style.FitScreen(form,850,570);var root=Style.Grid(1,34,-100,37);root.Padding=new Padding(12);int divider=guide.Details.IndexOf("\n\nExposure:");string sky=divider>=0?guide.Details.Substring(0,divider):guide.Sky;string plan=sky+"\n\nExposure: "+guide.Exposure+"\n\nGain: "+guide.Gain+"\n\nStarting goal: "+guide.Integration;string notes=guide.Notes+"\n\nSmart telescopes: gain is app-controlled. Use only exposure choices confirmed in your app for the selected model, firmware and mode. Original S50 DSO choices are 10/20/30 s; the Alt-Az starting plan uses 10 s. Other profiles use conservative verified choices. Lunar/planet modes have separate controls.\n\nCameras: documented HCG gain is a starting point, not a universal optimum. Verify the driver/read mode and check test frames for clipped stars. An unverified model needs a calibrated preset or your own gain override.\n\nBortle-based integration goals are estimates; they do not replace measured sky and sensor calibration.";string sources="Selected device:\n"+guide.DeviceSource+"\n\nLight-pollution baseline:\nhttps://lightpollutionmap.app/\n\nSeestar model comparison:\nhttps://helpdesk.zwoastro.com/hc/en-us/articles/48476700259213\n\nCalibrated exposure measurements:\nhttps://docs.sharpcap.co.uk/4.0/15_SmartHistogram.htm\n\nSee Capture guidance.txt and EquipmentLibrary for the rules and model sources.";string[] names={"Capture plan","Notes & limits","Sources"},texts={plan,notes,sources};var navigation=Style.Grid(4,-100);for(int i=0;i<3;i++){navigation.ColumnStyles[i].SizeType=SizeType.Absolute;navigation.ColumnStyles[i].Width=135;}navigation.ColumnStyles[3].Width=100;var content=new Panel{Dock=DockStyle.Fill,BackColor=Style.Card,Padding=new Padding(14),Margin=new Padding(0,2,0,6),Tag="guidance-content"};var text=new TextBox{Multiline=true,ReadOnly=true,Dock=DockStyle.Fill,ScrollBars=ScrollBars.None,BorderStyle=BorderStyle.None,BackColor=Style.Card,ForeColor=Style.Text,Font=new Font("Segoe UI",10),Tag="guidance-text"};content.Controls.Add(text);var buttons=new List<SectionButton>();Action<int> select=index=>{text.Text=texts[index].Replace("\r\n","\n").Replace("\n",Environment.NewLine);for(int i=0;i<buttons.Count;i++){buttons[i].Selected=i==index;buttons[i].Invalidate();}};for(int i=0;i<3;i++){int section=i;var button=new SectionButton{Text=names[i],Dock=DockStyle.Fill,Margin=new Padding(0,0,5,0),AccessibleRole=AccessibleRole.PageTab,AccessibleName=names[i]};button.Click+=(a,b)=>select(section);buttons.Add(button);navigation.Controls.Add(button,i,0);}select(0);root.Controls.Add(navigation,0,0);root.Controls.Add(content,0,1);root.Controls.Add(Style.Button("Close",(a,b)=>form.Close()),0,2);form.Controls.Add(root);return form;}
    public static void Show(CaptureGuide guide,Form owner){using(var form=Create(guide))form.ShowDialog(owner);}
}
}



